  T["freigabe-bestaetigen"]={html:"<h2 class=\"sr-only\">{{t:ui.confirm_for}}</h2>\n<style>\n.gw-btn{padding:9px 16px;border-radius:var(--radius);font:inherit;font-size:14px;font-weight:500;cursor:pointer}\n.gw-btn:disabled{opacity:0.45;cursor:default}\n.gw-ck{display:flex;align-items:flex-start;gap:8px;font-size:14px;line-height:1.5;color:var(--text-secondary)}\n.gw-ck[data-state=\"ok\"]{color:var(--text-success)}\n.gw-ck[data-state=\"warn\"]{color:var(--text-warning)}\n.gw-ck[data-state=\"block\"]{color:var(--text-danger)}\n</style>\n<div style=\"padding:1rem 0\">\n  <div id=\"gw-freigabe\" data-kind=\"{{APPROVAL_KIND}}\" data-revoke=\"{{APPROVAL_REVOKE}}\" data-id=\"{{TARGET_ID}}\" data-label=\"{{TARGET_LABEL}}\" data-title=\"{{APPROVAL_TITLE}}\" style=\"border:0.5px solid var(--border);border-radius:16px;background:var(--surface-1);padding:var(--pad-lg);display:flex;flex-direction:column;gap:var(--gap-md)\">\n    <div style=\"display:flex;align-items:center;gap:var(--gap-sm)\">\n      <i class=\"ti ti-circle-check\" id=\"gw-icon\" style=\"font-size:18px;color:var(--text-secondary)\" aria-hidden=\"true\"></i>\n      <span style=\"font-size:16px;font-weight:500\">{{APPROVAL_TITLE}}</span>\n    </div>\n    <div style=\"display:grid;grid-template-columns:auto 1fr;gap:6px var(--gap-md);align-items:baseline;padding:var(--pad-md);border:0.5px solid var(--border);border-radius:var(--radius);background:var(--surface-2)\">\n      <span style=\"font-size:13px;color:var(--text-muted)\">{{t:ui.applies_to}}</span><span style=\"font-size:14px;color:var(--text-primary)\">{{TARGET_LABEL}}</span>\n      <span style=\"font-size:13px;color:var(--text-muted)\">{{t:ui.version}}</span><span style=\"font-size:13px;font-family:var(--font-mono);color:var(--text-primary)\">{{HEAD_SHORT}}</span>\n    </div>\n    <div data-gw-if=\"CHECKS\" style=\"display:flex;flex-direction:column;gap:6px\">\n      {{#CHECKS}}\n      <div class=\"gw-ck\" data-state=\"{{CHECK_STATE}}\"><i class=\"ti\" style=\"font-size:16px;margin-top:2px\" aria-hidden=\"true\"></i><span>{{CHECK_TEXT}}</span></div>\n      {{/CHECKS}}\n    </div>\n    <p style=\"margin:0;font-size:14px;line-height:1.6;color:var(--text-secondary)\">{{APPROVAL_EFFECT}}</p>\n    <div style=\"display:flex;justify-content:flex-end;align-items:center;gap:var(--gap-sm);flex-wrap:wrap;border-top:0.5px solid var(--border);padding-top:var(--pad-md)\">\n      <span id=\"gw-blocked\" style=\"font-size:13px;color:var(--text-danger);margin-right:auto\" hidden>{{t:ui.complete_the_items_marked_in_red_first}}</span>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-cancel\" style=\"border:0.5px solid var(--border-strong);background:transparent;color:var(--text-primary)\">{{t:ui.cancel}}</button>\n      <button type=\"button\" class=\"gw-btn\" id=\"gw-save\" style=\"border:0.5px solid var(--border-accent);background:var(--bg-accent);color:var(--text-accent)\">{{APPROVAL_BUTTON}}</button>\n    </div>\n  </div>\n</div>\n",run:function(tr){
function gwSend(text,action,data){var d=GW.withHead(action,data||{}),k=Object.keys(d),short=k.every(function(x){var v=d[x];return typeof v==='number'||typeof v==='boolean'||(typeof v==='string'&&/^[^\s`]{1,80}$/.test(v));});sendPrompt(short?text+'\n\n`gw:'+action+k.map(function(x){return ' '+x+'='+d[x];}).join('')+'`':text+'\n\n```gw\n'+JSON.stringify(Object.assign({action:action},d))+'\n```');}
(function(){
  var f=document.getElementById('gw-freigabe'),d=f.dataset;
  var $=function(id){return document.getElementById(id);};
  var icons={ok:'ti-circle-check',warn:'ti-alert-triangle',block:'ti-circle-x'};
  var blocked=false;
  f.querySelectorAll('.gw-ck').forEach(function(c){c.querySelector('i').classList.add(icons[c.dataset.state]||'ti-point');if(c.dataset.state==='block')blocked=true;});
  $('gw-icon').className='ti '+(d.kind==='writing'?(d.revoke==='true'?'ti-pencil-off':'ti-pencil'):d.kind==='image'?(d.revoke==='true'?'ti-arrow-back-up':'ti-circle-check'):(d.revoke==='true'?'ti-lock-open':'ti-lock'));
  if(blocked){$('gw-save').disabled=true;$('gw-blocked').hidden=false;}
  function lock(){f.querySelectorAll('button').forEach(function(x){x.disabled=true;});f.style.opacity='0.6';}
  $('gw-save').addEventListener('click',function(){
    if(blocked)return;
    var data={kind:d.kind};data[d.kind==='chapter'?'chapter_id':'section_id']=d.id;if(d.revoke==='true')data.revoke=true;
    lock();gwSend(d.title+': '+d.label+tr("ui.confirmed"),'approval.confirm',data);
  });
  $('gw-cancel').addEventListener('click',function(){
    var data={form:'approval.confirm'};data[d.kind==='chapter'?'chapter_id':'section_id']=d.id;
    lock();gwSend(d.title+tr("ui.action_fragment_2"),'form.cancel',data);
  });
})();

}};
